(7506010, 1196518, 183174, '<td valign="top">?Drake</td>', '?Drake', '2017-03-22 09:13:23.000000', NULL, 1),
(7506013, 1197218, 183264, '<td valign="top">This is the pinnacle of photography.</td>', 'This is the pinnacle of photography.', '2017-03-22 09:27:00.000000', NULL, 1),
(7506017, 1196916, 163081, '<td valign="top">It''s already difficult to get sharp underwater shots, you made it even more challenging to capture a moving organism. Technically difficult. Maybe some cleanup in the background would make it pop more. A 6 from me.</td>', 'It''s already difficult to get sharp underwater shots, you made it even more challenging to capture a moving organism. Technically difficult. Maybe some cleanup in the background would make it pop more. A 6 from me.', '2017-03-22 10:29:55.000000', NULL, 1),
(7506019, 1197251, 163081, '<td valign="top">This is too over-over saturated, but I must admit that it has some appealing effect when reviewing it as standalone picture. I can see this hanging in an art gallery. A 7 from me.</td>', 'This is too over-over saturated, but I must admit that it has some appealing effect when reviewing it as standalone picture. I can see this hanging in an art gallery. A 7 from me.', '2017-03-22 10:32:31.000000', NULL, 1),
(7506020, 1196633, 163081, '<td valign="top">I really like the strong saturation in this image. For sure I would have cropped  10% off from the left side (where the building starts). In my top 10. An 8 from me.</td>', 'I really like the strong saturation in this image. For sure I would have cropped  10% off from the left side (where the building starts). In my top 10. An 8 from me.', '2017-03-22 10:39:15.000000', NULL, 1),
(7506024, 1196798, 163081, '<td valign="top">This would have been a famous picture in the 70''s. The choice of colors are flashy and almost hurting my eyes, but it is greatly composed and finally all comes together blended as a whole. A 6 from me</td>', 'This would have been a famous picture in the 70''s. The choice of colors are flashy and almost hurting my eyes, but it is greatly composed and finally all comes together blended as a whole. A 6 from me', '2017-03-22 10:42:26.000000', NULL, 1),
(7506026, 1197226, 163081, '<td valign="top">Wow, great perspective. I can''t imagine someone going up or down the street... The tittle is the only thing I don''t really like. In my top 10 and a 9 from me.</td>', 'Wow, great perspective. I can''t imagine someone going up or down the street... The tittle is the only thing I don''t really like. In my top 10 and a 9 from me.', '2017-03-22 10:46:56.000000', NULL, 1),
(7506038, 1197009, 163081, '<td valign="top">Making the picture a little darker and it would benefit the over-saturation much more. I like the longer exposure effect on the people very much. If you moved more to the right and get right in front of the gallery entrance, you should get a more appealing symmetry. A 6 from me.</td>', 'Making the picture a little darker and it would benefit the over-saturation much more. I like the longer exposure effect on the people very much. If you moved more to the right and get right in front of the gallery entrance, you should get a more appealing symmetry. A 6 from me.', '2017-03-22 11:05:05.000000', NULL, 1),
